import { scrapPerCost } from "./progression.js?v=041ed0015b08";
import { offerTier, moduleStat } from "./rarity.js?v=041ed0015b08";
import { rarityBadge, equipmentDescription } from "./equipment-ui.js?v=041ed0015b08";
import { MODULE_BY_ID, CHASSIS_BY_ID, BOSS_BY_ID, WAVES, label } from "./content.js?v=041ed0015b08";
import * as economy from "./economy.js?v=041ed0015b08";
import { supportFeedback } from "./workshop.js?v=041ed0015b08";
const escape = (value) => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
export function workshopMarkup(r, o) {
    const t = (zh, en) => o.lang === 'zh' ? zh : en, name = (item) => escape(label(item, o.lang));
    const selected = o.selected, act = Math.ceil(r.wave / 4), wave = WAVES[r.wave - 1], boss = BOSS_BY_ID[r.bosses[act - 1]], chassis = CHASSIS_BY_ID[r.chassis];
    const equipped = r.items.filter(i => !i.stored), power = equipped.reduce((n, i) => n + MODULE_BY_ID[i.id].power, 0), check = economy.validateLoadout(r), inactive = economy.inactiveSupports(r).length;
    const feedback = selected ? supportFeedback(r, selected.uid, o.lang) : undefined;
    const selectedDef = selected ? MODULE_BY_ID[selected.id] : undefined, merge = selected ? economy.previewMerge(r, selected.uid) : undefined;
    return `<div class="prep-wrap compact-workshop">
 <header class="run-strip"><div><strong>${t('装配台', 'WORKSHOP')}</strong><small>${t('第', 'WAVE ')} ${r.wave} ${t('场', '')} · ${name(chassis)}</small></div><div class="run-resources"><span>HP <b>${Math.ceil(r.hp)}</b></span><span class="scrap">⬡ ${Math.floor(r.gold)}</span><button data-action="workshop-more" aria-label="${t('装配帮助与战报', 'Workshop help and report')}">⋯</button></div></header>
 <div class="workshop-grid"><section class="workbench" aria-label="${t('背包装配', 'Loadout board')}">
 <div class="board-meta"><span>${t('电力', 'POWER')} <b class="${power > economy.getCapacity(r) ? 'invalid' : ''}">${power}/${economy.getCapacity(r)}</b></span><span>${t('占格', 'CELLS')} <b>${equipped.reduce((n, i) => n + economy.getCells(i).length, 0)}/${21 + r.unlockedCorners.length}</b></span><span>${t('武器', 'GUNS')} <b>${equipped.filter(i => MODULE_BY_ID[i.id].kind === 'weapon').length}/3</b></span></div>
 <div class="board-holder"><canvas id="backpack-canvas" width="750" height="750" aria-label="${t('5乘5背包，选择模块后点击空格放置', '5 by 5 backpack. Select a module, then tap a cell.')}" tabindex="0"></canvas></div>
 <div class="board-actions"><button data-action="rotate">↻ ${t('旋转', 'Rotate')}</button><button data-action="autopack">▦ ${t('整理', 'Arrange')}</button><button data-action="undo-edit" ${o.undo ? '' : 'disabled'}>↶ ${t('撤销', 'Undo')}</button>${o.pendingBuy >= 0 ? `<button data-action="cancel-buy">${t('取消', 'Cancel')}</button>` : ''}</div>
 <div class="rack"><span class="rack-title">${t('备件', 'RESERVE')}</span><div class="rack-slots">${Array.from({ length: 3 }, (_, i) => { const item = r.items.filter(v => v.stored)[i]; return item ? `<button class="rack-slot filled rarity-${item.tier} ${item.uid === selected?.uid ? 'selected' : ''}" data-action="select" data-uid="${item.uid}" title="${name(MODULE_BY_ID[item.id])}">${o.icon(item.id)}<span>${name(MODULE_BY_ID[item.id])}${rarityBadge(item.tier, o.lang)}</span></button>` : '<div class="rack-slot">＋</div>'; }).join('')}</div></div>
 ${o.placement}
 </section><aside class="shop-panel">
 <nav class="workshop-tabs" aria-label="${t('装配面板', 'Workshop panels')}">${['shop', 'module', 'route'].map((tab, index) => `<button data-action="workshop-tab" data-id="${tab}" aria-pressed="${o.tab === tab}" class="${o.tab === tab ? 'active' : ''}">${[t('商店', 'Shop'), t('模块', 'Module'), t('路线 / 事件', 'Route / Event')][index]}${tab === 'route' && r.eventId && !r.eventResolved ? '<i>●</i>' : ''}</button>`).join('')}</nav>
 <div class="prep-tab-panel" ${o.tab === 'shop' ? '' : 'hidden'}><div class="shop-tools"><button data-action="rarity-help" title="${t('查看稀有度与当前概率', 'Rarity and current odds')}">◇ ${t('稀有度', 'Rarity')}</button><button data-action="repair">${t('维修', 'Repair')} ⬡ ${Math.ceil([18, 24, 30][act - 1] * (r.difficulty >= 3 ? 1.25 : 1))}</button><button data-action="refresh">↻ ${t('刷新', 'Roll')} ⬡ ${Math.min(10, (r.refreshes + 1) * 2)}</button>${r.saleUndo ? `<button data-action="undo-sale">${t('撤销出售', 'Undo sale')}</button>` : ''}</div><div class="shop-grid">${r.shop.map((offer, index) => { const m = MODULE_BY_ID[offer.id], tier = offerTier(offer), canMerge = economy.purchaseMergeTargets(r, index).length > 0; return m ? `<article class="shop-card rarity-${tier} ${offer.locked ? 'locked' : ''}"><button class="shop-inspect" data-action="preview-buy" data-index="${index}" ${r.wave === 1 ? 'disabled' : ''}>${o.icon(m.id)}<span>${rarityBadge(tier, o.lang)}<strong>${name(m)}</strong><small>${moduleStat(m.id, tier, o.lang)} · <b>⬡ ${economy.offerPrice(offer)}</b></small></span>${canMerge ? `<i class="merge-available">${t('可合成', 'Combine')}</i>` : ''}</button><button class="lock-offer" data-action="lock" data-index="${index}" aria-label="${t('锁定', 'Lock ')}${name(m)}">${offer.locked ? '◆' : '◇'}</button></article>` : `<article class="shop-card sold">${t('已售出', 'SOLD')}</article>`; }).join('')}</div></div>
 <div class="prep-tab-panel module-panel" ${o.tab === 'module' ? '' : 'hidden'}>${selected && selectedDef ? `<div class="module-title rarity-${selected.tier}">${o.icon(selected.id)}<div><strong>${name(selectedDef)} ${rarityBadge(selected.tier, o.lang)}</strong><small>${selected.stored ? t('备件 · 尚未生效', 'Reserve · inactive') : t('已装备', 'Equipped')}</small></div><button data-action="module-details">${t('详情', 'Details')}</button></div><div class="detail-actions">${selected.stored ? '' : `<button data-action="store">${t('移入备件', 'Store')}</button>`}<button class="merge-button" data-action="preview-merge" ${merge?.ok ? '' : 'disabled'} title="${escape(merge?.ok ? t('消耗另一件同名同阶装备，免费升阶', 'Consume a matching copy to combine for free') : (o.lang === 'zh' ? merge?.reason : merge?.reasonEn))}">${selected.tier === 4 ? t('已达传说', 'Max rarity') : merge?.ok ? t('合成升阶 ↑', 'Combine ↑') : t('缺少同阶装备', 'Need a matching copy')}</button><button data-action="sell">${t('出售', 'Sell')} +${Math.floor(economy.standardCost(selected) * .5)}</button></div>${selectedDef.kind === 'support' && !selected.stored ? `<select id="link-select" aria-label="${t('连接武器', 'Linked weapon')}"><option value="">${t('选择相邻武器', 'Link adjacent weapon')}</option>${economy.linkOptions(r, selected.uid).map(({ weapon, result }) => `<option value="${weapon.uid}" ${selected.link === weapon.uid ? 'selected' : ''} ${result.ok ? '' : 'disabled'}>${name(MODULE_BY_ID[weapon.id])}${result.ok ? '' : ' · ' + escape(o.lang === 'zh' ? result.reason : result.reasonEn)}</option>`).join('')}</select>` : ''}<p>${escape(feedback?.detail ?? equipmentDescription(selected, o.lang))}</p>` : `<p class="empty-selection">${t('点击背包或备件中的模块，查看连接、合成与出售。', 'Select a board or reserve module to link, combine or sell it.')}</p>`}</div>
 <div class="prep-tab-panel route-panel" ${o.tab === 'route' ? '' : 'hidden'}>${o.event || `<p>${t('这一站没有额外事件。', 'No extra event at this stop.')}</p>`}${r.mode !== 'prototype' && wave.kind !== 'boss' && r.wave > 1 ? `<p>${t('货仓：敌人预算 +15%，过关额外 30 碎片。精英挑战：增加精英，过关额外模块。', 'Freight: +15% enemy budget, +30 scrap on clear. Elite challenge: extra elite, bonus module on clear.')}</p><div class="route-options">${[t('普通路线', 'Standard'), t('货仓 +30碎片', 'Freight +30'), t('精英挑战', 'Elite challenge')].map((text, i) => `<button class="${r.route === i ? 'active' : ''}" data-action="route" data-index="${i}">${text}</button>`).join('')}</div>` : ''}<p>${wave.kind === 'boss' ? t('首领战：躲开预警，利用攻击后的空窗。', 'Boss: dodge warnings and punish recovery.') : t(`生存至倒计时结束；击杀掉落价值为首场的 ${(scrapPerCost(r.wave) / .4).toFixed(1)} 倍，记得拾取金色碎片。`, `Survive the timer; each kill drops ${(scrapPerCost(r.wave) / .4).toFixed(1)}× the first wave's scrap value.`)}</p></div>
 </aside></div><footer class="workshop-deploy"><button class="loadout-summary ${check.ok ? '' : 'invalid'}" data-action="loadout-details"><strong>${wave.kind === 'boss' ? name(boss) : t(`下一场 · 生存 ${wave.duration} 秒`, `Next · survive ${wave.duration}s`)}</strong><span>${check.ok ? (inactive ? '⚠ ' + t(`${inactive} 件配件未生效 · 可继续出击`, `${inactive} inactive supports · can deploy`) : '✓ ' + t('装配就绪', 'Ready')) : escape(o.lang === 'zh' ? check.reason : check.reasonEn)}</span></button><button class="primary" data-action="deploy">${r.phase !== 'prep' ? t('领取奖励', 'Claim reward') : t('出击 ↗', 'Deploy ↗')}</button></footer></div>`;
}
